		return FastSub(PiOver2, Acos(value));
	}

	public static FPFloat Acos(FPFloat x)
	{
		if (x < -One || x > One)
		{
			throw new ArgumentOutOfRangeException("Must between -FP.One and FP.One", "x");
		}
		if (x.RawValue == 0L)
		{
			return PiOver2;
		}
		FPFloat fPFloat = Atan(Sqrt(One - x * x) / x);
		if (x.RawValue >= 0)
		{
			return fPFloat;
		}
		return fPFloat + Pi;
	}

