	internal static void GenerateAcosLut()
	{
		using StreamWriter streamWriter = new StreamWriter("FPAcosLut.cs");
		streamWriter.Write("namespace Orange.FixedPoint {\r\n    partial struct FPFloat {\r\n        public static readonly long[] AcosLut = new[] {");
		int num = 0;
		for (int i = 0; i < 25735; i++)
		{
			float num2 = (float)i / 25734f;
			if (num++ % 8 == 0)
			{
				streamWriter.WriteLine();
				streamWriter.Write("            ");
			}
			long rawValue = ((FPFloat)Math.Acos(num2))._rawValue;
			streamWriter.Write($"0x{rawValue:X}L, ");
		}
		streamWriter.Write("\r\n        };\r\n    }\r\n}");
	}

