	private unsafe static void* MemSet(char* buf, char c, int size)
	{
		char* ptr = buf;
		while (size > 0)
		{
			*ptr = c;
			size--;
			ptr++;
		}
		return buf;
	}

	private unsafe static void MemCopy(char* from, char* to, int len)
	{
		char* ptr = from;
		char* ptr2 = to;
		while (len > 0)
		{
			*ptr2 = *ptr;
			len--;
			ptr++;
			ptr2++;
		}
	}

	private static int IntPow(int baseNum, int exp)
	{
		int num = 1;
		while (exp != 0)
		{
			if ((exp & 1) == 1)
			{
				num *= baseNum;
			}
			exp >>= 1;
			baseNum *= baseNum;
		}
		return num;
	}

	private unsafe static void ClearTempChars()
	{
		fixed (char* tempChars = TempChars)
		{
			MemSet(tempChars, '<', TempChars.Length);
		}
	}

	public unsafe static FPFloat Parse(string str)
	{
		if (string.IsNullOrEmpty(str))
		{
			return Zero;
		}
		ClearTempChars();
		int num = Math.Min(TempChars.Length, str.Length);
		if (num > 0)
		{
			fixed (char* ptr = str)
			{
				fixed (char* tempChars = TempChars)
				{
					MemCopy(ptr, tempChars, num);
				}
			}
		}
		int num2 = 0;
		int num3 = 0;
		int num4 = 0;
		bool flag = true;
		int num5 = 0;
		bool flag2 = TempChars[0] == '-';
		int num6 = 0;
		if (flag2 || TempChars[0] == '+')
		{
			num6 = 1;
		}
		for (int i = num6; i < num; i++)
		{
			int num7 = TempChars[i];
			if (num7 < 43 || num7 > 60 || num5 > 1)
			{
				throw new Exception(str + " is not legal!!!!");
			}
			switch (num7)
			{
			case 46:
				flag = false;
				num5++;
				continue;
			default:
			{
				int num8 = TempChars[i] - 48;
				if (flag)
				{
					num2 = num2 * 10 + num8;
					continue;
				}
				num3 = num3 * 10 + num8;
				num4++;
				continue;
			}
			case 60:
				break;
			}
			break;
		}
		return (num2 + (FPFloat)num3 / (FPFloat)IntPow(10, num4)) * ((!flag2) ? 1 : (-1));
	}
}
